export function Chip({
  label = "{{label}}",
  variant = "{{variant}}",
  color = "{{color}}",
  selected = {{selected}},
  removable = {{removable}},
}) {
  const palette = {
    filled: { background: color, borderColor: color },
    outline: { background: "transparent", borderColor: color },
    tonal: { background: `color-mix(in srgb, ${color} 30%, #FAF7F2)`, borderColor: "transparent" },
  }[variant] ?? {};
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontWeight: 500, fontSize: 13,
      lineHeight: 1, padding: "6px 10px", borderRadius: 999, border: "1.5px solid", boxSizing: "border-box",
      color: "#241430", boxShadow: selected ? "0 0 0 2px #241430" : "none", ...palette }}>
      {label}
      {removable && (
        <button type="button" aria-label={`Remove ${label}`} style={{ border: "none", background: "transparent",
          color: "inherit", fontSize: 13, lineHeight: 1, cursor: "pointer", padding: 0, opacity: 0.7 }}>×</button>
      )}
    </span>
  );
}
